import java.util.Scanner;

public class Main {
    static final int MO = 1000000007;
    static final int oo = 0x3f3f3f3f;
    static final int MAXN = 100005;
    static final int MAXM = 1000005;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int P = sc.nextInt();
        int K = sc.nextInt();

        if (K == 0) {
            System.out.println(qpow(P, P - 1));
            return;
        }

        if (K == 1) {
            System.out.println(qpow(P, P));
            return;
        }

        boolean[] vis = new boolean[MAXM];
        int p = 1;
        int count = 0;
        while (!vis[p]) {
            count++;
            vis[p] = true;
            p = (int)((long)K * p % P);
        }

        System.out.println(qpow(P, P / count));
    }

    static int qpow(int x, int n) {
        long ans = 1;
        long base = x;
        int exp = n;
        while (exp != 0) {
            if ((exp & 1) != 0) {
                ans = (ans * base) % MO;
            }
            base = (base * base) % MO;
            exp >>= 1;
        }
        return (int) ans;
    }
}
